def functions(file):
 raw=file.read_text();tree=ast.parse(raw);out={}
 def walk(nodes,prefix=''):
  for node in nodes:
   if isinstance(node,ast.ClassDef):walk(node.body,prefix+node.name+'.')
   elif isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)):
    text=ast.get_source_segment(raw,node);out[prefix+node.name]={'line':node.lineno,'end_line':node.end_lineno,'sha256_utf8':hashlib.sha256(text.encode()).hexdigest(),'text':text,'calls':sorted({ast.unparse(n.func)for n in ast.walk(node)if isinstance(n,ast.Call)})}
 walk(tree.body);return out
